select public.admin_notify('🔔 Popup chhupne wali bug fix ho gayi', 'Aapki Chrome me "Collapse unwanted requests" ON hai — isliye Allow-popup ki jagah URL bar me chhota bell-icon aata tha jo chhoot jata tha (kuch BLOCK nahi tha — aapke screenshots ne yahi sabit kiya). Naya fix live: (1) 📲 dabane par pehle samjhane wala modal aata hai, (2) popup chhupa to sahi guide aati hai, (3) 🩺 button poori jaanch-report dikhta hai. Sabse aasan: Chrome Settings → Site settings → Notifications → "Expand all requests" chunein → panel NAYE tab me kholein → 📲 → BADA popup → Allow. Register hote hi test push khud aayegi.', 'session_end') as notified;
